// Schema compatibility check in CI/CD pipeline
public class SchemaCompatibilityValidator {

    public boolean validateCompatibility(String subject, Schema newSchema) {
        SchemaRegistryClient client = new CachedSchemaRegistryClient(
            "http://schema-registry:8081", 100);

        try {
            // Check backward compatibility (new schema can read old data)
            List<String> incompatibilities = client.testCompatibility(
                subject, new AvroSchema(newSchema), true);

            if (!incompatibilities.isEmpty()) {
                log.error("Schema incompatible: {}", incompatibilities);
                return false;
            }
            return true;
        } catch (Exception e) {
            throw new SchemaValidationException("Compatibility check failed", e);
        }
    }
}

// Apache Spark ETL pipeline for data warehouse loading (Java API)
import org.apache.spark.sql.*;
import org.apache.spark.sql.types.*;
import io.delta.tables.DeltaTable;
import java.util.*;
import java.util.stream.Collectors;
import static org.apache.spark.sql.functions.*;

public class OrderDataWarehouseETL {

    public static SparkSession createSparkSession() {
        return SparkSession.builder()
                .appName("OrderDataWarehouseETL")
                .config("spark.sql.extensions", "io.delta.sql.DeltaSparkSessionExtension")
                .config("spark.sql.catalog.spark_catalog", "org.apache.spark.sql.delta.catalog.DeltaCatalog")
                .config("spark.sql.adaptive.enabled", "true")
                .config("spark.sql.adaptive.coalescePartitions.enabled", "true")
                .config("spark.sql.shuffle.partitions", "200")
                .getOrCreate();
    }

    /** Extract orders from source database using JDBC with partition pruning. */
    public static Dataset<Row> extractOrders(SparkSession spark, String datePartition) {
        return spark.read()
                .format("jdbc")
                .option("url", "jdbc:postgresql://orders-db:5432/orders")
                .option("dbtable", String.format(
                    "(SELECT * FROM orders WHERE created_at::date = '%s') AS t", datePartition))
                .option("user", "etl_reader")
                .option("password", getSecret("orders-db-password"))
                .option("fetchsize", "10000")
                .option("numPartitions", "8")
                .option("partitionColumn", "order_id")
                .option("lowerBound", "1")
                .option("upperBound", "10000000")
                .load();
    }

    /** Apply business transformations and data quality rules. */
    public static Dataset<Row> transformOrders(Dataset<Row> ordersDf) {
        return ordersDf
                .withColumn("order_date", col("created_at").cast("date"))
                .withColumn("year", year(col("created_at")))
                .withColumn("month", month(col("created_at")))
                .withColumn("day", dayofmonth(col("created_at")))
                .withColumn("amount_usd",
                    when(col("currency").equalTo("EUR"), col("amount").multiply(1.08))
                    .when(col("currency").equalTo("GBP"), col("amount").multiply(1.26))
                    .otherwise(col("amount")))
                .withColumn("customer_segment",
                    when(col("total_lifetime_value").gt(10000), lit("enterprise"))
                    .when(col("total_lifetime_value").gt(1000), lit("mid-market"))
                    .otherwise(lit("smb")))
                .withColumn("surrogate_key", sha2(concat_ws("||",
                    col("order_id"), col("created_at")), 256))
                .withColumn("etl_loaded_at", current_timestamp())
                .filter(col("amount").gt(0))
                .filter(col("status").isin("completed", "refunded", "partially_refunded"))
                .dropDuplicates("order_id");
    }

    /** Upsert into Delta Lake table with merge semantics. */
    public static void loadToDelta(SparkSession spark, Dataset<Row> transformedDf, String targetPath) {
        if (DeltaTable.isDeltaTable(spark, targetPath)) {
            DeltaTable deltaTable = DeltaTable.forPath(spark, targetPath);

            deltaTable.alias("target").merge(
                transformedDf.alias("source"),
                "target.order_id = source.order_id"
            ).whenMatched("source.updated_at > target.updated_at")
                .updateExpr(Map.of(
                    "status", "source.status",
                    "amount", "source.amount",
                    "amount_usd", "source.amount_usd",
                    "updated_at", "source.updated_at",
                    "etl_loaded_at", "source.etl_loaded_at"
                ))
            .whenNotMatched()
                .insertAll()
            .execute();
        } else {
            transformedDf.write()
                .format("delta")
                .partitionBy("year", "month")
                .mode("overwrite")
                .save(targetPath);
        }
    }

    /** Post-load data quality validation. */
    public static Map<String, Long> runDataQualityChecks(SparkSession spark, String targetPath) {
        Dataset<Row> df = spark.read().format("delta").load(targetPath);

        Map<String, Long> checks = new LinkedHashMap<>();
        checks.put("nullOrderIds", df.filter(col("order_id").isNull()).count());
        checks.put("negativeAmounts", df.filter(col("amount").lt(0)).count());
        checks.put("futureDates", df.filter(col("created_at").gt(current_timestamp())).count());
        checks.put("duplicateOrders", df.count() - df.dropDuplicates("order_id").count());

        Map<String, Long> failures = checks.entrySet().stream()
                .filter(e -> e.getValue() > 0)
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));

        if (!failures.isEmpty()) {
            throw new DataQualityException("Quality checks failed: " + failures);
        }

        return checks;
    }

    // Main execution
    public static void main(String[] args) {
        SparkSession spark = createSparkSession();
        String datePartition = args[0]; // e.g., "2024-01-15"

        Dataset<Row> orders = extractOrders(spark, datePartition);
        Dataset<Row> transformed = transformOrders(orders);
        loadToDelta(spark, transformed, "s3://data-lake/warehouse/orders");
        runDataQualityChecks(spark, "s3://data-lake/warehouse/orders");
    }
}

// Reactive Streams backpressure with Project Reactor
@Service
public class EventProcessingPipeline {

    private final Sinks.Many<RawEvent> eventSink;
    private final EventProcessor processor;
    private final MetricsRegistry metrics;

    public EventProcessingPipeline(EventProcessor processor, MetricsRegistry metrics) {
        this.processor = processor;
        this.metrics = metrics;

        // Bounded buffer with overflow strategy
        this.eventSink = Sinks.many().multicast()
            .onBackpressureBuffer(10_000, false);

        // Processing pipeline with backpressure-aware operators
        eventSink.asFlux()
            .onBackpressureBuffer(
                5000,
                event -> metrics.increment("events.dropped"),
                BufferOverflowStrategy.DROP_OLDEST
            )
            .flatMap(event -> processWithRetry(event), 
                     64)  // Concurrency limit
            .buffer(Duration.ofSeconds(1), 100)  // Micro-batch for efficiency
            .flatMap(batch -> writeBatch(batch))
            .doOnError(e -> metrics.increment("pipeline.errors"))
            .retry(3)
            .subscribe();
    }

    public void ingest(RawEvent event) {
        Sinks.EmitResult result = eventSink.tryEmitNext(event);
        if (result.isFailure()) {
            metrics.increment("events.rejected");
            // Apply backpressure to upstream (return HTTP 429 or Kafka pause)
            throw new BackpressureException("Pipeline at capacity");
        }
    }

    private Mono<ProcessedEvent> processWithRetry(RawEvent event) {
        return Mono.fromCallable(() -> processor.process(event))
            .timeout(Duration.ofSeconds(5))
            .retryWhen(Retry.backoff(3, Duration.ofMillis(100))
                .maxBackoff(Duration.ofSeconds(2))
                .filter(e -> e instanceof TransientException));
    }
}

